Use prefix dynamic programming, retaining only the previous two counts. A digit 1–9 extends the previous prefix; a pair 10–26 extends the prefix two positions back. Empty input and leading zeros return 0.

```javascript
function solve(s) {
  if (s.length === 0 || s[0] === '0') return 0;

  let twoBack = 1;
  let oneBack = 1;

  for (let i = 1; i < s.length; i++) {
    let current = s[i] !== '0' ? oneBack : 0;

    if (
      s[i - 1] === '1' ||
      (s[i - 1] === '2' && s[i] <= '6')
    ) {
      current += twoBack;
    }

    twoBack = oneBack;
    oneBack = current;
  }

  return oneBack;
}
```

